  "landingFeatures.documentTitle": "امکانات سیستم | {{siteTitle}}",
  "landingFeatures.metaDescription": "امکانات کامل سامانه آرایشگران شامل نوبت‌دهی ۲۴ ساعته، پیامک یادآوری، کمپین هدفمند، فروشگاه آنلاین، سایت اختصاصی و مدیریت تیم.",
  "landingFeatures.badge": "همه امکانات سیستم به صورت کامل",
  "landingFeatures.title": "امکانات سیستم مخصوص رشد آرایشگران",
  "landingFeatures.intro.1": "این صفحه تمام قابلیت‌های سامانه را یکجا و شفاف نمایش می‌دهد.",
  "landingFeatures.intro.2": "هر بخش با نگاه نتیجه کسب‌وکاری طراحی شده تا مستقیم روی درآمد اثر بگذارد.",
  "landingFeatures.intro.3": "از نوبت‌دهی و یادآوری خودکار تا بازگردانی مشتری و فروش مکمل، همه چیز یکپارچه است.",
  "landingFeatures.intro.4": "سایت اختصاصی و مدیریت تیم هم کنار همین امکانات فعال می‌شود.",
