  "landingAbout.documentTitle": "درباره ما | {{siteTitle}}",
  "landingAbout.metaDescription": "آشنایی با تیم حرفه‌ای سامانه جامع آرایشگران، تخصص‌ها، توانمندی‌ها و رویکرد ما در طراحی و توسعه سیستم‌های رشد‌محور برای کسب‌وکارهای زیبایی.",
  "landingAbout.badge": "ما چه تیمی هستیم؟",
  "landingAbout.title": "یک تیم حرفه‌ای برای ساخت سیستم‌های رشد‌محور",
  "landingAbout.intro.1": "ما یک تیم محصول و توسعه هستیم که روی نیاز واقعی کسب‌وکارهای خدماتی کار می‌کنیم.",
  "landingAbout.intro.2": "هدف ما فقط ساخت یک نرم‌افزار نیست؛ ساخت سیستمی است که واقعاً به افزایش درآمد و نظم کمک کند.",
  "landingAbout.intro.3": "در طراحی و پیاده‌سازی، تجربه کاربری، پایداری فنی و نتیجه عملیاتی را همزمان جلو می‌بریم.",
  "landingAbout.intro.4": "تمرکز اصلی ما در این پروژه، رشد برند شخصی آرایشگران و سالن‌های زیبایی است.",
  "landingAbout.intro.5": "هر قابلیت با منطق کسب‌وکاری طراحی می‌شود تا خروجی قابل اندازه‌گیری داشته باشد.",
  "landingAbout.capability.ux.title": "طراحی تجربه کاربری حرفه‌ای",
  "landingAbout.capability.ux.description": "رابط‌های ساده، سریع و قابل فهم که کاربر واقعی بدون آموزش پیچیده از آن استفاده کند.",
  "landingAbout.capability.tech.title": "پیاده‌سازی فنی پایدار",
  "landingAbout.capability.tech.description": "توسعه استاندارد با تمرکز روی پرفورمنس، امنیت و مقیاس‌پذیری برای رشد بلندمدت کسب‌وکار.",
