  "panelNutritionSettings.photoAnalysis.title": "امکان عکس از غذا و تحلیل کالری برای کاربران",
  "panelNutritionSettings.photoAnalysis.description": "اگر روشن باشد، داخل بخش ثبت غذای خارج از برنامه کاربر می‌تواند از غذا عکس بگیرد یا تصویرش را آپلود کند تا سیستم غذا را تشخیص دهد، کالری را تخمین بزند و مقدار مناسب همان وعده را پیشنهاد بدهد. اگر خاموش باشد، ثبت غذای خارج از برنامه فقط به‌صورت دستی باقی می‌ماند و مسیر عکس و تحلیل AI نمایش داده نمی‌شود.",
