  "nutritionWellnessPreview.pageAudioTitle": "ویس‌های صفحه {{page}}",
  "nutritionWellnessPreview.pageAudioDescription": "برای هر صفحه توصیه متنی، می‌توان چند فایل صوتی جداگانه هم قرار داد تا کاربر توضیح مربی را بشنود.",
  "nutritionWellnessPreview.generalAudioTitle": "ویس‌های عمومی سبک سلامتی",
  "nutritionWellnessPreview.generalAudioDescription": "چند توصیه صوتی کلی که در تمام این برنامه قابل استفاده هستند.",
  "nutritionWellnessPreview.downloadPdf": "دانلود نسخه PDF",
  "nutritionWellnessPreview.pages.1.title": "نگهداری وزن بدون سخت‌گیری",
  "nutritionWellnessPreview.pages.1.subtitle": "پایه ذهنی این مسیر، ثبات است نه فشار",
  "nutritionWellnessPreview.pages.1.note": "اگر وزن شما در محدوده مطلوب است، هدف این برنامه فقط حفظ ریتم سالم زندگی است.",
  "nutritionWellnessPreview.pages.1.paragraph.1": "در این مدل رژیم، قرار نیست هر وعده با عدد و گرم کنترل شود. تمرکز اصلی روی انتخاب‌های پایدار، وعده‌های منظم و جلوگیری از بازگشت عادت‌های پرخوری است.",
  "nutritionWellnessPreview.pages.1.paragraph.2": "برای نگه داشتن وزن، مهم‌ترین اصل این است که بیشتر روزهای هفته شبیه هم باشند؛ نه اینکه چند روز خیلی خوب و چند روز کاملاً رها باشیم.",
  "nutritionWellnessPreview.pages.1.checklist.1": "صبحانه را حذف نکن.",
  "nutritionWellnessPreview.pages.1.checklist.2": "بین وعده‌های اصلی ریزه‌خواری نداشته باش.",
  "nutritionWellnessPreview.pages.1.checklist.3": "وزن را فقط هفته‌ای یک بار ثبت کن.",
  "nutritionWellnessPreview.pages.2.title": "ریتم وعده‌ها در روزهای عادی",
  "nutritionWellnessPreview.pages.2.subtitle": "بدن با نظم، بهتر از محدودیت جواب می‌دهد",
  "nutritionWellnessPreview.pages.2.note": "در بیشتر روزها سه وعده اصلی کافی است و فقط در صورت نیاز میان‌وعده سبک اضافه شود.",
  "nutritionWellnessPreview.pages.2.paragraph.1": "بهتر است ساعت غذا خوردن در طول هفته تا حد امکان منظم باشد. این موضوع هم اشتها را متعادل می‌کند و هم جلوی خوردن‌های ناگهانی را می‌گیرد.",
  "nutritionWellnessPreview.pages.2.paragraph.2": "اگر روزی اشتها کمتر بود، حجم غذا را کم کن ولی وعده را حذف نکن تا عصر یا شب به پرخوری نرسی.",
  "nutritionWellnessPreview.pages.2.checklist.1": "صبحانه تا یک ساعت بعد از بیدار شدن.",
  "nutritionWellnessPreview.pages.2.checklist.2": "ناهار در بازه ثابت روزانه.",
  "nutritionWellnessPreview.pages.2.checklist.3": "شام سبک و زودتر از همیشه.",
  "nutritionWellnessPreview.pages.3.title": "آرام کردن ولع و هوس غذایی",
  "nutritionWellnessPreview.pages.3.subtitle": "همه گرسنگی‌ها واقعی نیستند",
  "nutritionWellnessPreview.pages.3.note": "وقتی میل ناگهانی به شیرینی یا تنقلات می‌آید، اول باید تشخیص دهیم خستگی است یا گرسنگی واقعی.",
  "nutritionWellnessPreview.pages.3.paragraph.1": "بسیاری از مواقعی که میل شدید به خوراکی ایجاد می‌شود، بدن در واقع دنبال استراحت، آب، یا یک وقفه کوتاه ذهنی است.",
  "nutritionWellnessPreview.pages.3.paragraph.2": "اگر بین وعده‌ها هوس شدید داشتی، اول یک لیوان آب بخور، ۱۰ دقیقه صبر کن و بعد تصمیم بگیر.",
  "nutritionWellnessPreview.pages.3.checklist.1": "قبل از هر هوس، آب بنوش.",
  "nutritionWellnessPreview.pages.3.checklist.2": "اگر خواب کم بوده، خوردن را درمان خستگی نکن.",
  "nutritionWellnessPreview.pages.3.checklist.3": "تنقلات را خارج از دید نگه دار.",
  "nutritionWellnessPreview.pages.4.title": "تحرک سبک برای حفظ فرم بدن",
  "nutritionWellnessPreview.pages.4.subtitle": "حرکت کم اما مداوم بهتر از تمرین مقطعی است",
  "nutritionWellnessPreview.pages.4.note": "برای نگهداری وزن، لازم نیست تمرین سنگین داشته باشی؛ پیاده‌روی مداوم هم اثر زیادی دارد.",
  "nutritionWellnessPreview.pages.4.paragraph.1": "اگر در دوره کاهش وزن یا افزایش وزن نیستی، هدف از فعالیت بدنی در این مرحله فقط بالا نگه داشتن متابولیسم و حال خوب روزانه است.",
  "nutritionWellnessPreview.pages.4.paragraph.2": "حتی ۲۰ تا ۳۰ دقیقه پیاده‌روی در روز می‌تواند کمک بزرگی برای حفظ وزن و کنترل اشتها باشد.",
  "nutritionWellnessPreview.pages.4.checklist.1": "حداقل ۵ روز در هفته پیاده‌روی.",
  "nutritionWellnessPreview.pages.4.checklist.2": "بعد از غذا کمی راه برو.",
  "nutritionWellnessPreview.pages.4.checklist.3": "زمان نشستن طولانی را بشکن.",
  "nutritionWellnessPreview.pages.5.title": "خواب و آرامش در سبک سلامتی",
  "nutritionWellnessPreview.pages.5.subtitle": "خواب خوب بخشی از رژیم است",
  "nutritionWellnessPreview.pages.5.note": "بدن خسته، انتخاب‌های عجولانه‌تری انجام می‌دهد و اشتها را سخت‌تر کنترل می‌کند.",
  "nutritionWellnessPreview.pages.5.paragraph.1": "وقتی خواب کافی نباشد، میل به غذاهای پرکالری و شیرین بیشتر می‌شود. برای حفظ وزن، خواب شبانه منظم به اندازه انتخاب غذا اهمیت دارد.",
  "nutritionWellnessPreview.pages.5.paragraph.2": "سعی کن ساعت خواب و بیداری در بیشتر روزها نزدیک به هم باشد تا بدن در یک الگوی آرام بماند.",
  "nutritionWellnessPreview.pages.5.checklist.1": "شام را خیلی دیر نخور.",
  "nutritionWellnessPreview.pages.5.checklist.2": "قبل از خواب سراغ خوراکی شیرین نرو.",
  "nutritionWellnessPreview.pages.5.checklist.3": "نور موبایل را قبل از خواب کم کن.",
  "nutritionWellnessPreview.pages.6.title": "جمع‌بندی سبک زندگی پایدار",
  "nutritionWellnessPreview.pages.6.subtitle": "ثبات کوچک، نتیجه بزرگ می‌سازد",
  "nutritionWellnessPreview.pages.6.note": "موفقیت این برنامه به کامل بودن نیست؛ به تکرار رفتارهای درست در اکثر روزها بستگی دارد.",
  "nutritionWellnessPreview.pages.6.paragraph.1": "اگر یک وعده یا یک روز از برنامه فاصله گرفت، لازم نیست همه چیز را رها کنی. کافی است از وعده بعدی دوباره به ریتم اصلی برگردی.",
  "nutritionWellnessPreview.pages.6.paragraph.2": "این مدل سلامت‌محور برای کسانی مناسب است که می‌خواهند وزن خود را حفظ کنند، بدنشان در تعادل بماند و غذا خوردنشان حس طبیعی داشته باشد.",
  "nutritionWellnessPreview.pages.6.checklist.1": "از فردا شروع نکن، از وعده بعدی شروع کن.",
  "nutritionWellnessPreview.pages.6.checklist.2": "پایبندی ۸۰ درصدی کاملاً کافی است.",
  "nutritionWellnessPreview.pages.6.checklist.3": "ثبات هفتگی مهم‌تر از سخت‌گیری روزانه است.",
